package ug.audiocity.studio;
import java.io.*;import java.util.*;
/** Offline spectral-peak pitch-class analysis. Suggestions, never a guarantee of the intended melody. */
public final class KeyDetector {
 static final int N=4096,DECIMATE=4;static final double RATE=12000;
 static final double[][] PROFILES={{6.35,2.23,3.48,2.33,4.38,4.09,2.52,5.19,2.39,3.66,2.29,2.88},{6.33,2.68,3.52,5.38,2.60,3.53,2.54,4.75,3.98,2.69,3.34,3.17}};
 public static final class Result {public int root,scale,alternativeRoot,alternativeScale,tonalFrames,pitchClasses;public double score,margin;public boolean confident;public String name(){return PocketComposer.ROOTS[root]+(scale==1?" major":" minor");}public String alternative(){return PocketComposer.ROOTS[alternativeRoot]+(alternativeScale==1?" major":" minor");}}
 static final class Peak {double midi,weight;Peak(double m,double w){midi=m;weight=w;}}
 static void fft(double[] real,double[] imag){int n=real.length;for(int i=1,j=0;i<n;i++){int b=n>>1;for(;(j&b)!=0;b>>=1)j^=b;j^=b;if(i<j){double r=real[i];real[i]=real[j];real[j]=r;r=imag[i];imag[i]=imag[j];imag[j]=r;}}for(int size=2;size<=n;size<<=1){double angle=-2*Math.PI/size,cr=Math.cos(angle),ci=Math.sin(angle);for(int start=0;start<n;start+=size){double wr=1,wi=0;for(int j=0;j<size/2;j++){int a=start+j,b=a+size/2;double tr=wr*real[b]-wi*imag[b],ti=wr*imag[b]+wi*real[b];real[b]=real[a]-tr;imag[b]=imag[a]-ti;real[a]+=tr;imag[a]+=ti;double r=wr*cr-wi*ci;wi=wr*ci+wi*cr;wr=r;}}}}
 static int mask(int root,int scale){int m=0;for(int n:scale==1?new int[]{0,2,4,5,7,9,11}:new int[]{0,2,3,5,7,8,10})m|=1<<((root+n)%12);return m;}
 static double correlation(double[] x,int root,int scale){double[] p=PROFILES[scale-1];double mx=0,mp=0;for(int i=0;i<12;i++){mx+=x[i];mp+=p[i];}mx/=12;mp/=12;double xy=0,xx=0,pp=0;for(int i=0;i<12;i++){double a=x[i]-mx,b=p[Math.floorMod(i-root,12)]-mp;xy+=a*b;xx+=a*a;pp+=b*b;}return xy/Math.sqrt(Math.max(1e-20,xx*pp));}
 public static Result analyse(Core.Source source)throws IOException {
  if(source.frames()<Core.RATE*3)throw new IOException("Choose at least three seconds of pitched backing audio.");int windows=Math.min(96,Math.max(12,source.frames()/(N*DECIMATE/2)));ArrayList<Peak> all=new ArrayList<>();Result result=new Result();double tuneX=0,tuneY=0;double[] real=new double[N],imag=new double[N],mag=new double[N/2+1],median=new double[31];int lo=(int)Math.ceil(55*N/RATE),hi=(int)Math.floor(1800*N/RATE);
  for(int window=0;window<windows;window++){long at=(long)((source.frames()-N*DECIMATE)*window/(double)Math.max(1,windows-1));Arrays.fill(imag,0);double low=0,low2=0,alpha=1-Math.exp(-2*Math.PI*2200/Core.RATE),energy=0;for(int i=0;i<N*DECIMATE;i++){int frame=(int)at+i;double v=(source.sample(frame,0)+source.sample(frame,1))*.5;low+=alpha*(v-low);low2+=alpha*(low-low2);if(i%DECIMATE==0){int j=i/DECIMATE;real[j]=low2*(.5-.5*Math.cos(2*Math.PI*j/(N-1)));energy+=low2*low2;}}if(energy/N<1e-6)continue;fft(real,imag);double power=0;for(int i=0;i<mag.length;i++){mag[i]=Math.hypot(real[i],imag[i]);if(i>=lo&&i<=hi)power+=mag[i]*mag[i];}ArrayList<Peak> peaks=new ArrayList<>();double peakPower=0;
   for(int i=lo;i<=hi;i++){if(mag[i]<=mag[i-1]||mag[i]<mag[i+1])continue;for(int j=-15;j<=15;j++)median[j+15]=mag[Math.max(0,Math.min(mag.length-1,i+j))];Arrays.sort(median);double residual=mag[i]-median[15]*2;if(residual<=0)continue;double l=Math.log(Math.max(1e-15,mag[i-1])),m=Math.log(Math.max(1e-15,mag[i])),r=Math.log(Math.max(1e-15,mag[i+1])),den=l-2*m+r,delta=Math.abs(den)>1e-12?Math.max(-.5,Math.min(.5,.5*(l-r)/den)):0;double hz=(i+delta)*RATE/N;peaks.add(new Peak(69+12*Math.log(hz/440)/Math.log(2),Math.sqrt(residual)));peakPower+=mag[i]*mag[i];}
   if(peaks.size()<3||peakPower/Math.max(1e-15,power)<.25)continue;result.tonalFrames++;double sum=0;for(Peak p:peaks)sum+=p.weight;for(Peak p:peaks){p.weight/=sum;all.add(p);double angle=2*Math.PI*(p.midi-Math.rint(p.midi));tuneX+=Math.cos(angle)*p.weight;tuneY+=Math.sin(angle)*p.weight;}
  }
  if(result.tonalFrames<6)throw new IOException("Not enough stable harmony detected. Choose a longer backing with bass or chords, or set the key manually.");double offset=Math.atan2(tuneY,tuneX)/(2*Math.PI);double[] chroma=new double[12];for(Peak p:all){int note=(int)Math.round(p.midi-offset);if(Math.abs(p.midi-offset-note)<.32)chroma[Math.floorMod(note,12)]+=p.weight;}double max=0;for(double v:chroma)max=Math.max(max,v);for(double v:chroma)if(v>max*.12)result.pitchClasses++;
  double best=-2;for(int scale=1;scale<=2;scale++)for(int root=0;root<12;root++){double score=correlation(chroma,root,scale);if(score>best){best=score;result.root=root;result.scale=scale;}}result.score=best;double second=-2;for(int scale=1;scale<=2;scale++)for(int root=0;root<12;root++)if(mask(root,scale)!=mask(result.root,result.scale)){double score=correlation(chroma,root,scale);if(score>second){second=score;result.alternativeRoot=root;result.alternativeScale=scale;}}result.margin=best-second;result.confident=result.pitchClasses>=5&&result.score>=.72&&result.margin>=.04;return result;
 }
}
